def maximumSaleItems(items, budget):
    n = len(items)

    # g[i] = number of other items j whose factor is a multiple of factor_i
    g = [0] * n
    for i in range(n):
        fi = items[i][0]
        for j in range(n):
            if i != j and items[j][0] % fi == 0:
                g[i] += 1

    # 0/1 knapsack: buying item i once costs price_i and yields 1 + g[i] copies
    # dp[c] = best number of copies with total spending at most c
    dp = [0] * (budget + 1)
    for i in range(n):
        price = items[i][1]
        gain = 1 + g[i]
        for c in range(budget, price - 1, -1):
            if dp[c - price] + gain > dp[c]:
                dp[c] = dp[c - price] + gain

    # Leftover money buys extra copies of the cheapest item, worth 1 copy each
    pmin = items[0][1]
    for i in range(n):
        if items[i][1] < pmin:
            pmin = items[i][1]

    best = 0
    for c in range(budget + 1):
        total = dp[c] + (budget - c) // pmin
        if total > best:
            best = total
    return best
